package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.medical.persistence.FormalInputFixture.*;
final class ExpertScoreAuthorityTest {
 ExpertFixture f;ExpertEvaluationFixture e;JsonNode qualification;
 @BeforeEach void prepare()throws Exception{f=new ExpertFixture();qualification=f.author();f.approve(qualification);f.now=f.now.plusMinutes(1);e=new ExpertEvaluationFixture(f);}
 @AfterEach void close()throws Exception{f.close();}
 void code(ErrorCode expected,org.junit.jupiter.api.function.Executable action){var x=ExpertQualificationServiceTest.cause(assertThrows(Exception.class,action));assertInstanceOf(TenantAccessException.class,x);assertEquals(expected,((TenantAccessException)x).code());}
 @Test void productionScoreCannotAppendWithoutFormalScoringGate()throws Exception{
  when(e.scoringGates.getIfAvailable()).thenReturn(null);
  code(ErrorCode.DEPENDENCY_UNAVAILABLE,e::append);
  assertTrue(e.scores.isEmpty());assertTrue(e.stored.isEmpty());assertTrue(e.operations.isEmpty());assertTrue(f.scoreAuthorities.isEmpty());
 }
 @Test void productionScoreCannotAppendWithRevokedFormalScoringGate()throws Exception{
  doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(e.scoringGate).require(any(),anyString(),any(),any());
  code(ErrorCode.ACCESS_DENIED,e::append);
  verify(e.scoringGate).prepare(eq(f.f.subject),eq("1"),eq(e.definition.evaluation_id()),any(byte[].class));
  assertTrue(e.scores.isEmpty());assertTrue(e.stored.isEmpty());assertTrue(e.operations.isEmpty());assertTrue(f.scoreAuthorities.isEmpty());
 }
 @Test void formalScoringGateRechecksTheSamePreparedObservationAfterOriginalAppend()throws Exception{
  e.append();
  verify(e.scoringGate,times(2)).require(eq(f.f.admission),eq(e.definition.evaluation_id()),eq(e.preparedObservation),same(e.scoringPrepared));
 }
 @Test void actualOriginalAppendSynchronouslyPersistsImmutableHistoricalGrantAndMode()throws Exception{var response=e.append();assertEquals(1,f.scoreAuthorities.size());var witness=f.scoreAuthorities.values().iterator().next();assertEquals(response.path("data").path("operation_id").asText(),witness.originalOperationId());assertEquals(f.expert,witness.createdBy());var content=f.schema.parse(witness.authorityJson().getBytes(java.nio.charset.StandardCharsets.UTF_8));assertEquals("local",content.path("identity_mode").asText());assertEquals(e.scores.get(0).authority_grant_id(),content.path("grant").path("grant_id").asText());assertEquals(3,f.audits.size());}
 @Test void sourceProofCannotEscapeOriginalScoreCallback()throws Exception{var retained=new AtomicReference<EvaluationService.CreatedScoreWitness>();e.sink(p->{retained.set(p);f.recorder.capture(p);});e.append();assertNotNull(retained.get());code(ErrorCode.ACCESS_DENIED,()->retained.get().score());code(ErrorCode.ACCESS_DENIED,()->f.recorder.capture(retained.get()));}
 @Test void sinkFailurePropagatesInsteadOfReturningSuccessfulScoreReceipt()throws Exception{e.sink(p->{p.requireCurrent();throw new java.io.IOException("synthetic sink persistence failure");});var error=ExpertQualificationServiceTest.cause(assertThrows(Exception.class,e::append));assertEquals("synthetic sink persistence failure",error.getMessage());assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());}
 @Test void disabledOptionalSinkPreservesScoreAndLeavesItUnqualified()throws Exception{e.sink(null);e.append();assertTrue(f.scoreAuthorities.isEmpty());e.finish();code(ErrorCode.OBJECT_UNAVAILABLE,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification)));assertTrue(f.bindings.isEmpty());}
 @Test void approvedExpertCanBindExactRealOriginalScoreAndProofDoesNotPromoteResult()throws Exception{e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);f.transaction(()->{var proof=f.authority.requireQualifiedScore(f.f.admission,basis);assertEquals(e.scores.get(0),proof.score());assertEquals(java.time.Instant.parse(e.scores.get(0).created_at()),proof.qualification().asOf());assertEquals(f.expert,proof.qualification().expertId());assertEquals(qualification.path("qualification"),f.schema.tree(proof.qualification().qualification()));proof.requireConsumer(f.f.admission,e.definition.evaluation_id(),e.scores.get(0).score_id());assertFalse(e.result.production_eligible());return null;});}
 @Test void anotherPublisherCannotTakeAnotherExpertsScoreAndApplyQualification()throws Exception{e.append();e.finish();f.actor(id(4));code(ErrorCode.ACCESS_DENIED,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification)));}
 @Test void missingHistoricalModeWitnessCannotBeBackfilledFromToday()throws Exception{e.append();e.finish();f.scoreAuthorities.clear();code(ErrorCode.OBJECT_UNAVAILABLE,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification)));assertTrue(f.scoreAuthorities.isEmpty());}
 @Test void originalAuthoritySnapshotTamperingIsRejectedEvenIfCurrentGrantWouldAllow()throws Exception{e.append();e.finish();var w=f.scoreAuthorities.values().iterator().next();f.audits.put(w.auditId(),"{}");code(ErrorCode.CONTENT_MISMATCH,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification)));}
 @Test void wrongScoreHashOrDifferentEvaluationCannotBorrowQualification()throws Exception{e.append();e.finish();var q=(com.fasterxml.jackson.databind.node.ObjectNode)e.bindRequest(qualification);q.put("score_sha256","0".repeat(64));code(ErrorCode.CONTENT_MISMATCH,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",q));}
 @Test void currentRevocationInvalidatesPreviouslyBoundScore()throws Exception{e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification));f.actor(id(4));f.service.decide(f.f.subject,"1","expert-revoke-binding-key",f.decision(qualification,"REVOKE","2"));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);code(ErrorCode.ACTION_STALE,()->f.transaction(()->f.authority.requireQualifiedScore(f.f.admission,basis)));}
 @Test void currentReadNeedsNoTodaysWriteGrantAndKeepsHistoricalMode()throws Exception{e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification));f.f.grants.removeIf(g->g.action().equals("evaluation.score")||g.action().equals("agent.publish")||g.action().equals("agent.configure"));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);f.transaction(()->{var proof=f.authority.requireQualifiedScore(f.f.admission,basis);proof.requireUnchanged();return null;});}
 @Test void acceptanceSnapshotRequiresSameAdmissionAndCurrentReadAuthority()throws Exception{e.append();e.finish();f.transaction(()->{var snapshot=e.service.requireAcceptance(f.f.admission,e.definition.evaluation_id());var foreign=mock(EnterpriseAccess.Admission.class);code(ErrorCode.ACCESS_DENIED,()->snapshot.requireConsumer(foreign,e.definition.evaluation_id()));f.f.grants.removeIf(g->g.action().equals("evaluation.read"));code(ErrorCode.ACCESS_DENIED,snapshot::requireUnchanged);return null;});}

 @Test void differentExpertCannotBorrowAnOtherwiseValidQualification()throws Exception{f.expert=id(5);e.append();e.finish();code(ErrorCode.CONTENT_MISMATCH,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification)));}
 @Test void differentDomainCannotBorrowQualification()throws Exception{e.append();e.finish();var q=(com.fasterxml.jackson.databind.node.ObjectNode)e.bindRequest(qualification);q.put("domain","Different professional scope");code(ErrorCode.CONTENT_MISMATCH,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",q));}
 @Test void approvalAfterActualScoreTimeCannotRetroactivelyQualifyIt()throws Exception{e.append();e.finish();f.now=f.now.plusMinutes(2);f.actor(ACTOR);var q=f.service.author(f.f.subject,"1","new-qualification-late-author",f.authorRequest());f.actor(id(4));f.service.decide(f.f.subject,"1","new-qualification-late-approve",f.decision(q,"APPROVE","1"));f.actor(f.expert);code(ErrorCode.ACCESS_DENIED,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(q)));}
 @Test void qualificationExpiredAtActualScoreTimeCannotBeUsed()throws Exception{f.now=f.now.plusDays(4);e.append();e.finish();code(ErrorCode.ACCESS_DENIED,()->f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification)));}
 @Test void verifiedQualificationCannotEscapeOriginalConsumerTransaction()throws Exception{e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);var proof=f.transaction(()->f.authority.requireQualifiedScore(f.f.admission,basis));code(ErrorCode.ACCESS_DENIED,()->f.transaction(()->{proof.requireUnchanged();return null;}));}
 @Test void verifiedQualificationRejectsWrongAdmissionProjectPurposeAndCell()throws Exception{e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);f.transaction(()->{var proof=f.authority.requireQualifiedScore(f.f.admission,basis);code(ErrorCode.ACCESS_DENIED,()->proof.requireConsumer(f.f.admission,id(999),e.scores.get(0).score_id()));code(ErrorCode.ACCESS_DENIED,()->proof.qualification().requireConsumer(f.f.admission,f.expert,"PTR expert review",id(999),"EVALUATION_RESULTS"));code(ErrorCode.ACCESS_DENIED,()->proof.qualification().requireConsumer(f.f.admission,f.expert,"PTR expert review",null,"OTHER_PURPOSE"));return null;});}
 @Test void finalResultHashChangeInvalidatesPreviouslyObtainedSnapshot()throws Exception{e.append();e.finish();f.transaction(()->{var snapshot=e.service.requireAcceptance(f.f.admission,e.definition.evaluation_id());e.status="FAILED";code(ErrorCode.CONTENT_MISMATCH,snapshot::requireUnchanged);return null;});}
 @Test void sourceDependencyWithdrawalInvalidatesCurrentQualifiedScoreRead()throws Exception{e.append();e.finish();var receipt=f.service.bindScore(f.f.subject,"1","expert-score-binding-key",e.bindRequest(qualification));f.f.grants.removeIf(g->g.action().equals("source.read"));var basis=f.schema.bind(receipt.path("record"),PermissionProtocol.Basis.class);code(ErrorCode.ACCESS_DENIED,()->f.transaction(()->f.authority.requireQualifiedScore(f.f.admission,basis)));}
 @Test void originalBindingKeyReplaysButDifferentKeyDoesNotDuplicateSameScoreQualification()throws Exception{e.append();e.finish();var q=e.bindRequest(qualification);var receipt=f.service.bindScore(f.f.subject,"1","expert-score-binding-key",q);assertEquals(receipt,f.service.bindScore(f.f.subject,"1","expert-score-binding-key",q));code(ErrorCode.ACTION_STALE,()->f.service.bindScore(f.f.subject,"1","another-score-binding-key",q));assertEquals(1,f.bindings.size());}
}
